const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const $=s=>document.querySelector(s);
const party=[
 {name:'LYRA',role:'TIDEBOUND',glyph:'✧',hp:112,maxHp:112,mp:28,maxMp:28,color:'#f2b878',turn:true},
 {name:'KAEL',role:'ASHEN KNIGHT',glyph:'⚔',hp:138,maxHp:138,mp:22,maxMp:22,color:'#85b5d8',turn:false},
 {name:'MOSS',role:'STAR WITCH',glyph:'✦',hp:96,maxHp:96,mp:36,maxMp:36,color:'#a8d69b',turn:false}
];
const enemies=[
 {name:'TIDE WRAITH',hp:76,maxHp:76,type:'wraith',alive:true},
 {name:'RIFTLING',hp:56,maxHp:56,type:'rift',alive:true},
 {name:'RIFTLING',hp:56,maxHp:56,type:'rift',alive:true}
];
let game={started:false,over:false,won:false,active:0,round:1,phase:'intro',sub:null,target:0,items:2,combo:0,guard:false,guardEnd:0,attackEnd:0,attackBonus:false,log:'The tide has brought <em>something ancient</em> to shore.',turn:0,anim:null,shake:0,charge:0};
let particles=[];let last=0;
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function text(t,x,y,size,color='#fff',font='monospace',align='left'){ctx.fillStyle=color;ctx.font=`${size}px ${font}`;ctx.textAlign=align;ctx.fillText(t,x,y)}
function path(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
function drawBackground(t){
 let g=ctx.createLinearGradient(0,0,0,440);g.addColorStop(0,'#1b2b40');g.addColorStop(.52,'#596878');g.addColorStop(.7,'#c28b71');g.addColorStop(1,'#243b43');ctx.fillStyle=g;ctx.fillRect(0,0,960,440);
 // stars and distant moon
 for(let i=0;i<42;i++){let x=(i*173+31)%960,y=(i*61+18)%190;rect(x,y,((i%3===0)?2:1),((i%3===0)?2:1),i%4?'#d9dfd3':'#f2ce90')}
 ctx.fillStyle='#ffe0a6';ctx.globalAlpha=.22;ctx.beginPath();ctx.arc(722,121,68,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#f9dca9';ctx.beginPath();ctx.arc(722,121,37,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e7c89c';ctx.beginPath();ctx.arc(736,112,36,0,Math.PI*2);ctx.fill();
 // far cliffs
 path([[0,195],[83,138],[132,170],[207,106],[285,162],[356,121],[442,177],[505,145],[573,184],[646,131],[730,178],[811,123],[890,164],[960,136],[960,316],[0,316]],'#354653');
 path([[0,231],[100,192],[178,217],[276,171],[358,231],[440,190],[531,227],[623,184],[700,225],[791,180],[873,213],[960,185],[960,337],[0,337]],'#293a43');
 // broken clock arch
 rect(467,157,12,105,'#263944');rect(476,155,91,12,'#263944');rect(552,162,12,104,'#263944');rect(488,167,10,77,'#53636a');rect(498,161,53,8,'#53636a');rect(544,170,8,66,'#53636a');rect(481,149,10,8,'#d7ad72');rect(551,151,10,8,'#d7ad72');
 // water and shimmer
 path([[0,294],[123,280],[218,299],[335,281],[443,300],[569,282],[693,298],[822,280],[960,296],[960,393],[0,393]],'#263e48');
 for(let i=0;i<38;i++){let x=(i*109+24)%960,y=300+(i*29)%82;rect(x,y,12+(i%4)*4,1,i%3?'#66817e':'#d0a47b')}
 // shore platform
 path([[0,348],[103,331],[221,340],[320,321],[449,342],[578,326],[710,340],[833,322],[960,343],[960,440],[0,440]],'#55564e');
 path([[0,348],[103,331],[221,340],[320,321],[449,342],[578,326],[710,340],[833,322],[960,343],[960,357],[0,372]],'#9a8066');
 // stones, grass and tide pools
 for(let i=0;i<90;i++){let x=(i*83+11)%960,y=365+(i*47)%74;let c=['#746b5c','#3d5150','#b18a69','#56615b'][i%4];rect(x,y,4+(i%4)*2,2,c)}
 rect(0,418,960,22,'#1d3037');rect(82,355,2,14,'#688068');rect(88,350,3,12,'#82916f');rect(330,350,2,13,'#72846e');rect(337,355,3,9,'#94a075');rect(911,349,3,12,'#71866b');
 // soft vignette
 let vg=ctx.createRadialGradient(480,220,150,480,220,600);vg.addColorStop(.45,'#0000');vg.addColorStop(1,'#07111b99');ctx.fillStyle=vg;ctx.fillRect(0,0,960,440);
}
function drawHero(i,x,y,t){let p=party[i],bob=Math.sin(t/270+i*1.7)*3,dy=y+bob;ctx.save();ctx.translate(x,dy);let col=i===0?'#d9a577':i===1?'#83a8bf':'#9ac78f';
 // shadow
 ctx.globalAlpha=.35;ctx.fillStyle='#101820';ctx.beginPath();ctx.ellipse(0,23,20,5,0,0,6.3);ctx.fill();ctx.globalAlpha=1;
 // legs / boots
 rect(-10,8,8,12,'#29363e');rect(2,8,8,12,'#29363e');rect(-12,18,11,4,'#a67f67');rect(1,18,12,4,'#a67f67');
 // cloak/body
 rect(-13,-12,26,21,i===0?'#c86d61':i===1?'#567e9d':'#546f62');rect(-16,-7,4,14,col);rect(12,-7,5,14,col);rect(-9,-17,18,8,'#e1c59c');
 // face and hair
 rect(-8,-27,16,13,'#dbad89');rect(-9,-30,18,7,i===0?'#633e3b':i===1?'#453d3c':'#d7d0ac');rect(-11,-25,4,9,i===0?'#633e3b':i===1?'#453d3c':'#d7d0ac');rect(3,-21,3,2,'#17232a');
 // signature
 if(i===0){rect(15,-9,3,28,'#d9c292');rect(13,-11,7,5,'#8de1d6');rect(16,-14,2,3,'#f9d783')}
 if(i===1){rect(14,-21,4,35,'#c7d6d3');rect(12,-24,8,4,'#e2c57f');rect(16,-27,3,5,'#e2c57f')}
 if(i===2){rect(-18,-16,3,35,'#9b795a');rect(-21,-20,9,7,'#b3d9a0');rect(-21,-24,3,4,'#f0dd95')}
 ctx.restore();
}
function drawEnemy(i,x,y,t){let e=enemies[i];if(!e.alive)return;let bob=Math.sin(t/230+i)*4,dy=y+bob;ctx.save();ctx.translate(x,dy);ctx.globalAlpha=.5;ctx.fillStyle='#101820';ctx.beginPath();ctx.ellipse(0,19,21,5,0,0,6.3);ctx.fill();ctx.globalAlpha=1;
 if(e.type==='wraith'){
 ctx.globalAlpha=.82;ctx.fillStyle='#70dddc';ctx.beginPath();ctx.moveTo(0,-35);ctx.lineTo(18,-16);ctx.lineTo(13,10);ctx.lineTo(0,20);ctx.lineTo(-16,9);ctx.lineTo(-20,-14);ctx.closePath();ctx.fill();ctx.globalAlpha=1;
 rect(-13,-19,26,17,'#90efdf');rect(-10,-27,20,10,'#b8f5db');rect(-8,-16,5,3,'#244450');rect(4,-16,5,3,'#244450');rect(-5,-5,10,3,'#37777b');rect(-15,7,8,7,'#56bebb');rect(8,7,8,7,'#56bebb');
 }else{
 ctx.globalAlpha=.9;ctx.fillStyle='#8c7cce';ctx.beginPath();ctx.moveTo(0,-26);ctx.lineTo(18,-9);ctx.lineTo(13,13);ctx.lineTo(-13,13);ctx.lineTo(-18,-9);ctx.closePath();ctx.fill();ctx.globalAlpha=1;rect(-13,-16,26,21,'#7967ba');rect(-10,-22,20,9,'#a391e4');rect(-8,-12,5,3,'#fff0bb');rect(4,-12,5,3,'#fff0bb');rect(-5,-3,10,3,'#44356e');rect(-17,1,7,7,'#b19bde');rect(10,1,7,7,'#b19bde');
 }
 // enemy HP gauge
 let bw=i===0?74:58, pct=Math.max(0,e.hp/e.maxHp);rect(-bw/2,-48,bw,4,'#10171d');rect(-bw/2,-48,bw*pct,4,i===0?'#63dbcf':'#b89bea');
 ctx.restore();}
function drawScene(t){let dx=game.shake>0?(Math.random()-.5)*game.shake:0;if(game.shake>0)game.shake*=.84;ctx.save();ctx.translate(dx,0);drawBackground(t);
 // glow under combatants
 for(let x of [214,275,336,654,790,886]){let g=ctx.createRadialGradient(x,345,1,x,345,47);g.addColorStop(0,'#f5cb8760');g.addColorStop(1,'#f5cb8700');ctx.fillStyle=g;ctx.fillRect(x-48,298,96,75)}
 // attack/guard effects behind
 drawEffects(t);
 enemies.forEach((e,i)=>drawEnemy(i,[658,790,886][i],[320,330,322][i],t));party.forEach((p,i)=>{if(p.hp>0)drawHero(i,[207,270,333][i],[334,342,334][i],t)});
 // target cursor
 if(game.started&&!game.over&&game.phase==='command'&&game.sub==='target'&&enemies[game.target]?.alive){let x=[658,790,886][game.target];text('▼',x,250,15,'#f3d37e','monospace','center');}
 // battle prompt overlay
 if(game.phase==='timing'&&game.started){drawTiming(t)}
 if(game.phase==='guard'&&game.started){drawGuard(t)}
 // intro/debrief overlay
 if(!game.started||game.over){ctx.fillStyle='#1019239c';ctx.fillRect(0,0,960,440);ctx.fillStyle='#172630ed';ctx.fillRect(260,104,440,230);ctx.strokeStyle='#c19f6c';ctx.lineWidth=1;ctx.strokeRect(260.5,104.5,439,229);text(!game.started?'A TIDE OUT OF TIME':game.won?'THE HOUR HOLDS':'THE TIDE TAKES ALL',480,153,13,'#f2cf89','monospace','center');
 if(!game.started){text('A broken clock. A shore that remembers.',480,190,17,'#f0e9d9','Georgia','center');text('Three wanderers. One last chance to turn the tide.',480,217,12,'#b7c5c6','monospace','center');text('TAKE YOUR STAND',480,281,11,'#8ce2d2','monospace','center');text('Press ENTER or click to begin',480,305,10,'#8b9b9f','monospace','center')}
 else {text(game.won?'The Meridian stirs beneath the waves.':'The shore falls silent once more.',480,193,15,'#f0e9d9','Georgia','center');text(game.won?'A new path opens beyond the broken clock.':'The tide will wait. Your story need not end here.',480,220,11,'#b7c5c6','monospace','center');text('PLAY AGAIN',480,280,11,'#8ce2d2','monospace','center');text('Press ENTER to begin again',480,305,10,'#8b9b9f','monospace','center')}
 }
 ctx.restore();}

function drawEffects(t){for(let i=particles.length-1;i>=0;i--){let p=particles[i],age=(t-p.born)/p.life;if(age>=1){particles.splice(i,1);continue}let a=1-age;ctx.globalAlpha=a; if(p.kind==='slash'){ctx.strokeStyle=p.color;ctx.lineWidth=5*a;ctx.beginPath();ctx.arc(p.x,p.y,25+age*38,p.start,p.start+2.4);ctx.stroke();ctx.strokeStyle='#fff4c4';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,27+age*38,p.start,p.start+2.4);ctx.stroke()}else if(p.kind==='ring'){ctx.strokeStyle=p.color;ctx.lineWidth=4*a;ctx.beginPath();ctx.arc(p.x,p.y,12+age*64,0,Math.PI*2);ctx.stroke()}else if(p.kind==='bolt'){ctx.strokeStyle=p.color;ctx.lineWidth=4*a;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.tx,p.ty);ctx.stroke();for(let j=0;j<4;j++){let q=j/4;rect(p.x+(p.tx-p.x)*q+(Math.random()-.5)*12,p.y+(p.ty-p.y)*q,3,7,'#fff5cf')}}else{rect(p.x+Math.sin(age*20)*12,p.y-age*45,3+Math.random()*3,3+Math.random()*3,p.color)}ctx.globalAlpha=1}}
function burst(x,y,color,n=18){let now=performance.now();for(let i=0;i<n;i++)particles.push({kind:'spark',x:x+(Math.random()-.5)*20,y:y+(Math.random()-.5)*18,color,born:now,life:450+Math.random()*500})}
function drawTiming(t){let p=game.action,elapsed=t-game.charge,progress=Math.min(1,elapsed/1100),x=310+progress*340;ctx.fillStyle='#101923e8';ctx.fillRect(270,272,420,75);ctx.strokeStyle='#76847e';ctx.strokeRect(270.5,272.5,419,74);text(p?.label==='Starfall'?'STARFALL · RELEASE ON THE GOLD':'STRIKE · RELEASE ON THE GOLD',480,292,10,'#f3d48f','monospace','center');rect(310,308,340,12,'#27353b');rect(310+340*.61,308,340*.14,12,'#e7b961');rect(x-3,302,6,24,'#f7f0d8');text('SPACE / ENTER',480,338,9,'#aab7b4','monospace','center')}
function drawGuard(t){let elapsed=t-game.charge,progress=Math.min(1,elapsed/1050),x=310+progress*340;ctx.fillStyle='#101923ed';ctx.fillRect(270,272,420,75);ctx.strokeStyle='#74877e';ctx.strokeRect(270.5,272.5,419,74);text(`${game.enemySource||'ENEMY'} · PARRY THE BLOW`,480,292,10,'#f3d48f','monospace','center');rect(310,308,340,12,'#27353b');rect(310+340*.36,308,340*.2,12,'#67c9a8');rect(x-3,302,6,24,'#f7f0d8');text('SPACE / ENTER',480,338,9,'#aab7b4','monospace','center')}
function setLog(s){game.log=s;$('#logline').innerHTML=s}
function aliveParty(){return party.map((p,i)=>p.hp>0?i:-1).filter(i=>i>=0)}
function renderParty(){let node=$('#party');node.innerHTML=party.map((p,i)=>{let pct=Math.max(0,p.hp/p.maxHp*100),mp=p.mp/p.maxMp*100;return `<article class="hero-card ${p.hp<=0?'down':''} ${game.started&&!game.over&&i===game.active&&game.phase==='command'?'active':''}">${game.started&&i===game.active&&game.phase==='command'?'<span class="ready">YOUR TURN</span>':''}<div class="hero-top"><div class="portrait" style="color:${p.color}">${p.glyph}</div><div><div class="hero-name">${p.name}</div><div class="hero-role">${p.role}</div></div></div><div class="hp-row"><span>HP</span><b>${p.hp} / ${p.maxHp}</b></div><div class="bar"><i style="width:${pct}%;background:${pct<30?'linear-gradient(90deg,#d65c54,#f28c70)':''}"></i></div><div class="mp-row"><span>MP ${p.mp}/${p.maxMp}</span><div class="mp-bar"><i style="width:${mp}%"></i></div></div></article>`}).join('');$('#partyStatus').textContent=party.filter(p=>p.hp>0).length+' SOULS · ONE FATE';$('#activeName').textContent=game.started&&!game.over&&game.phase==='command'?`${party[game.active].name} · ${party[game.active].role}`:game.started&&!game.over?'BATTLE IN MOTION':'AWAITING THE HOUR'};$('#turnLabel').innerHTML=game.started&&!game.over?`TURN ${game.round}<strong>${game.phase==='command'?'YOUR MOVE':'THE TIDE TURNS'}</strong>`:game.won?'THE HOUR HOLDS<strong>—</strong>':'THE HOUR IS FADING<strong>—</strong>';$('#footerStatus').textContent=game.started&&!game.over?(game.phase==='command'?'CHOOSE YOUR ACTION':'FATE IN MOTION'):'READY WHEN YOU ARE'}
function renderCommands(){let b=$('#commandBody');if(!game.started||game.over){b.innerHTML='';return}if(game.phase!=='command'){b.innerHTML=game.phase==='timing'?'<div class="subpanel"><button class="subbtn" id="tapBtn">✦ &nbsp;TIME YOUR STRIKE<small>PRESS SPACE WHEN THE MARKER HITS GOLD</small></button></div>':'<div class="subpanel"><button class="subbtn" id="tapBtn">◈ &nbsp;PARRY THE BLOW<small>PRESS SPACE WHEN THE MARKER HITS MINT</small></button></div>';$('#tapBtn').onclick=confirmTiming;return}
 let p=party[game.active];if(game.sub==='skills'){b.innerHTML=`<div class="subpanel"><button class="subbtn" data-skill="Tidal Cut" ${p.mp<5?'disabled':''}>〰 &nbsp;Tidal Cut <small>5 MP · single target · 31 dmg</small></button><button class="subbtn" data-skill="Starfall" ${p.mp<9?'disabled':''}>✦ &nbsp;Starfall <small>9 MP · all foes · 22 dmg</small></button><button class="back" id="back">← &nbsp;BACK TO COMMANDS</button></div>`;b.querySelectorAll('[data-skill]').forEach(x=>x.onclick=()=>chooseSkill(x.dataset.skill));$('#back').onclick=()=>{game.sub=null;renderCommands()};return}
 if(game.sub==='target'){b.innerHTML=`<div class="subpanel"><button class="subbtn" data-target="0" ${!enemies[0].alive?'disabled':''}>◉ &nbsp;${enemies[0].name} <small>${enemies[0].alive?enemies[0].hp+' / '+enemies[0].maxHp+' HP':'DEFEATED'}</small></button><button class="subbtn" data-target="1" ${!enemies[1].alive?'disabled':''}>◉ &nbsp;Riftling I <small>${enemies[1].alive?enemies[1].hp+' / '+enemies[1].maxHp+' HP':'DEFEATED'}</small></button><button class="subbtn" data-target="2" ${!enemies[2].alive?'disabled':''}>◉ &nbsp;Riftling II <small>${enemies[2].alive?enemies[2].hp+' / '+enemies[2].maxHp+' HP':'DEFEATED'}</small></button><button class="back" id="back">← &nbsp;BACK</button></div>`;b.querySelectorAll('[data-target]').forEach(x=>x.onclick=()=>{game.target=Number(x.dataset.target);beginAttack()});$('#back').onclick=()=>{game.sub=null;renderCommands()};return}
 b.innerHTML=`<div class="command-grid"><button class="cmd" id="attack">⚔ &nbsp;Attack <kbd>1</kbd></button><button class="cmd" id="skills">✦ &nbsp;Skills <kbd>2</kbd></button><button class="cmd" id="item" ${game.items<=0?'disabled':''}>◈ &nbsp;Tideglass <kbd>3</kbd></button><button class="cmd" id="guard">⛨ &nbsp;Guard <kbd>4</kbd></button></div>`;
 $('#attack').onclick=()=>{game.action={type:'attack',label:'Attack'};game.sub='target';game.target=firstAlive();renderCommands()};$('#skills').onclick=()=>{game.sub='skills';renderCommands()};$('#item').onclick=useItem;$('#guard').onclick=useGuard}
function firstAlive(){return enemies.findIndex(e=>e.alive)}
function chooseSkill(name){let p=party[game.active],cost=name==='Starfall'?9:5;if(p.mp<cost)return;p.mp-=cost;game.action={type:'skill',label:name,damage:name==='Starfall'?22:31,all:name==='Starfall'};if(name==='Starfall')beginAttack();else{game.sub='target';game.target=firstAlive();renderCommands()}renderParty()}
function beginAttack(){game.phase='timing';game.sub=null;game.charge=performance.now();game.attackBonus=false;setLog(`${party[game.active].name} steadies their stance. <em>Find the golden moment.</em>`);renderParty();renderCommands()}
function confirmTiming(){if(game.phase!=='timing')return;let p=Math.min(1,(performance.now()-game.charge)/1100);game.attackBonus=p>=.61&&p<=.75;resolveAttack()}
function resolveAttack(){let act=game.action;if(!act)return;let boost=game.attackBonus?1.7:1;let hits=[];if(act.all){enemies.forEach((e,i)=>{if(e.alive){e.hp=Math.max(0,e.hp-Math.round(act.damage*boost));if(!e.hp)e.alive=false;hits.push(i)}})}else{let e=enemies[game.target];if(e?.alive){let dmg=Math.round((act.type==='attack'?21:act.damage)*boost);e.hp=Math.max(0,e.hp-dmg);if(!e.hp)e.alive=false;hits.push(game.target)}}
 let names=hits.map(i=>enemies[i].name);if(act.label==='Starfall'){setLog(`${party[game.active].name} calls <em>Starfall</em> from the dark between hours!`);hits.forEach(i=>particles.push({kind:'bolt',x:200+Math.random()*130,y:92,tx:[658,790,886][i],ty:310,born:performance.now(),life:550}));hits.forEach(i=>setTimeout(()=>burst([658,790,886][i],315,'#b4a1f2',22),250))}
 else {let idx=hits[0]??game.target,x=[658,790,886][idx];if(act.label==='Tidal Cut'){setLog(`${party[game.active].name} unleashes <em>Tidal Cut</em>!`);particles.push({kind:'slash',x,y:313,color:'#67ead9',start:-2.7,born:performance.now(),life:500})}else{setLog(`${party[game.active].name} strikes for <em>${game.attackBonus?'perfect ':''}impact</em>!`);particles.push({kind:'slash',x,y:313,color:game.attackBonus?'#ffe39c':'#d8e2dd',start:-2.6,born:performance.now(),life:380})}burst(x,315,game.attackBonus?'#ffe39c':'#d9ece2',12);game.shake=game.attackBonus?8:4}
 if(game.attackBonus){game.combo=Math.min(100,game.combo+18);setLog(`${party[game.active].name} lands a <em>perfect strike!</em> The tide surges.`)}game.action=null;renderCommands();renderParty();if(enemies.every(e=>!e.alive)){winGame();return}finishHeroTurn()}

function useItem(){if(game.items<=0)return;let target=aliveParty().sort((a,b)=>party[a].hp/party[a].maxHp-party[b].hp/party[b].maxHp)[0];if(target===undefined)return;game.items--;let heal=Math.min(48,party[target].maxHp-party[target].hp);party[target].hp+=heal;particles.push({kind:'ring',x:[207,270,333][target],y:320,color:'#77e1d0',born:performance.now(),life:700});setLog(`A <em>Tideglass</em> breaks open. ${party[target].name} recovers ${heal} HP.`);renderParty();finishHeroTurn()}
function useGuard(){party[game.active].guarded=true;setLog(`${party[game.active].name} braces against the <em>coming tide</em>.`);particles.push({kind:'ring',x:[207,270,333][game.active],y:320,color:'#9ecfe0',born:performance.now(),life:650});finishHeroTurn()}
function finishHeroTurn(){game.sub=null;let next=-1;for(let i=game.active+1;i<party.length;i++)if(party[i].hp>0){next=i;break}if(next>=0){game.active=next;game.phase='command';setLog(`<em>${party[next].name}</em>, the hour is yours.`);renderParty();renderCommands()}else{game.phase='enemy';game.enemyIndex=0;renderParty();renderCommands();enemyAct()}}
function enemyAct(){if(game.over)return;if(enemies.every(e=>!e.alive)){winGame();return}if(game.enemyIndex>=enemies.length){game.round++;game.active=aliveParty()[0];if(game.active===undefined){loseGame();return}game.phase='command';setLog(`The tide recedes. <em>Turn ${game.round}</em> — choose your next move.`);renderParty();renderCommands();return}let e=enemies[game.enemyIndex];if(!e.alive){game.enemyIndex++;enemyAct();return}let live=aliveParty();if(!live.length){loseGame();return}game.enemyTarget=live[Math.floor(Math.random()*live.length)];game.enemySource=e.name;game.phase='guard';game.charge=performance.now();game.guardPerfect=false;setLog(`<em>${e.name}</em> surges toward ${party[game.enemyTarget].name}! Find the parry.`);renderParty();renderCommands()}
function confirmGuard(){if(game.phase!=='guard')return;let p=Math.min(1,(performance.now()-game.charge)/1050);game.guardPerfect=p>=.36&&p<=.57;resolveEnemyAttack()}
