function drawGuard(t){let p=Math.min(1,(t-game.charge)/1050),x=310+p*340;ctx.fillStyle='#101923ed';ctx.fillRect(270,272,420,75);ctx.strokeStyle='#74877e';ctx.strokeRect(270.5,272.5,419,74);text(`${game.enemySource||'ENEMY'} · PARRY THE BLOW`,480,292,10,'#f3d48f','monospace','center');rect(310,308,340,12,'#27353b');rect(310+340*.36,308,340*.2,12,'#67c9a8');rect(x-3,302,6,24,'#f7f0d8');text('SPACE / ENTER',480,338,9,'#aab7b4','monospace','center')}
