if(!game.started||game.over){ctx.fillStyle='#1019239c';ctx.fillRect(0,0,960,440);ctx.fillStyle='#172630ed';ctx.fillRect(260,104,440,230);ctx.strokeStyle='#c19f6c';ctx.lineWidth=1;ctx.strokeRect(260.5,104.5,439,229);text(!game.started?'A TIDE OUT OF TIME':game.won?'THE HOUR HOLDS':'THE TIDE TAKES ALL',480,153,13,'#f2cf89','monospace','center');if(!game.started){text('A broken clock. A shore that remembers.',480,190,17,'#f0e9d9','Georgia','center');text('Three wanderers. One last chance to turn the tide.',480,217,12,'#b7c5c6','monospace','center');text('TAKE YOUR STAND',480,281,11,'#8ce2d2','monospace','center');text('Press ENTER or click to begin',480,305,10,'#8b9b9f','monospace','center')}else{text(game.won?'The Meridian stirs beneath the waves.':'The shore falls silent once more.',480,193,15,'#f0e9d9','Georgia','center');text(game.won?'A new path opens beyond the broken clock.':'The tide will wait. Your story need not end here.',480,220,11,'#b7c5c6','monospace','center');text('PLAY AGAIN',480,280,11,'#8ce2d2','monospace','center');text('Press ENTER to begin again',480,305,10,'#8b9b9f','monospace','center')}}ctx.restore()}
function setLog(s){game.log=s;$('#logline').innerHTML=s}function aliveParty(){return party.map((p,i)=>p.hp>0?i:-1).filter(i=>i>=0)}
