function renderCommands(){let b=$('#commandBody');if(!game.started||game.over){b.innerHTML='';return}if(game.phase!=='command'){b.innerHTML=game.phase==='timing'?'<div class="subpanel"><button class="subbtn" id="tapBtn">✦ &nbsp;TIME YOUR STRIKE<small>PRESS SPACE WHEN THE MARKER HITS GOLD</small></button></div>':'<div class="subpanel"><button class="subbtn" id="tapBtn">◈ &nbsp;PARRY THE BLOW<small>PRESS SPACE WHEN THE MARKER HITS MINT</small></button></div>';$('#tapBtn').onclick=confirm;return}let p=party[game.active];if(game.sub==='skills'){b.innerHTML=`<div class="subpanel"><button class="subbtn" data-skill="Tidal Cut" ${p.mp<5?'disabled':''}>〰 &nbsp;Tidal Cut <small>5 MP · single target · 31 dmg</small></button><button class="subbtn" data-skill="Starfall" ${p.mp<9?'disabled':''}>✦ &nbsp;Starfall <small>9 MP · all foes · 22 dmg</small></button><button class="back" id="back">← &nbsp;BACK TO COMMANDS</button></div>`;b.querySelectorAll('[data-skill]').forEach(x=>x.onclick=()=>chooseSkill(x.dataset.skill));$('#back').onclick=()=>{game.sub=null;renderCommands()};return}if(game.sub==='target'){b.innerHTML=`<div class="subpanel"><button class="subbtn" data-target="0" ${!enemies[0].alive?'disabled':''}>◉ &nbsp;Tide Wraith <small>${enemies[0].alive?enemies[0].hp+' / 76 HP':'DEFEATED'}</small></button><button class="subbtn" data-target="1" ${!enemies[1].alive?'disabled':''}>◉ &nbsp;Riftling I <small>${enemies[1].alive?enemies[1].hp+' / 56 HP':'DEFEATED'}</small></button><button class="subbtn" data-target="2" ${!enemies[2].alive?'disabled':''}>◉ &nbsp;Riftling II <small>${enemies[2].alive?enemies[2].hp+' / 56 HP':'DEFEATED'}</small></button><button class="back" id="back">← &nbsp;BACK</button></div>`;b.querySelectorAll('[data-target]').forEach(x=>x.onclick=()=>{game.target=Number(x.dataset.target);beginAttack()});$('#back').onclick=()=>{game.sub=null;game.action=null;renderCommands()};return}b.innerHTML=`<div class="command-grid"><button class="cmd" id="attack">⚔ &nbsp;Attack <kbd>1</kbd></button><button class="cmd" id="skills">✦ &nbsp;Skills <kbd>2</kbd></button><button class="cmd" id="item" ${game.items<=0?'disabled':''}>◈ &nbsp;Tideglass <kbd>3</kbd></button><button class="cmd" id="guard">⛨ &nbsp;Guard <kbd>4</kbd></button></div>`;$('#attack').onclick=()=>{game.action={type:'attack',label:'Attack'};game.sub='target';game.target=firstAlive();renderCommands()};$('#skills').onclick=()=>{game.sub='skills';renderCommands()};$('#item').onclick=useItem;$('#guard').onclick=useGuard}
function firstAlive(){return enemies.findIndex(e=>e.alive)}function chooseSkill(name){let p=party[game.active],cost=name==='Starfall'?9:5;if(p.mp<cost)return;p.mp-=cost;game.action={type:'skill',label:name,damage:name==='Starfall'?22:31,all:name==='Starfall'};if(name==='Starfall')beginAttack();else{game.sub='target';game.target=firstAlive();renderCommands()}renderParty()}
function beginAttack(){game.phase='timing';game.sub=null;game.charge=performance.now();game.attackBonus=false;setLog(`${party[game.active].name} steadies their stance. <em>Find the golden moment.</em>`);renderParty();renderCommands()}
function confirmTiming(){if(game.phase!=='timing')return;let p=Math.min(1,(performance.now()-game.charge)/1100);game.attackBonus=p>=.61&&p<=.75;resolveAttack()}
function resolveAttack(){let act=game.action;if(!act)return;let boost=game.attackBonus?1.7:1,hits=[];if(act.all){enemies.forEach((e,i)=>{if(e.alive){e.hp=Math.max(0,e.hp-Math.round(act.damage*boost));if(!e.hp)e.alive=false;hits.push(i)}})}else{let e=enemies[game.target];if(e?.alive){let dmg=Math.round((act.type==='attack'?21:act.damage)*boost);e.hp=Math.max(0,e.hp-dmg);if(!e.hp)e.alive=false;hits.push(game.target)}}if(act.label==='Starfall'){setLog(`${party[game.active].name} calls <em>Starfall</em> from the dark between hours!`);hits.forEach(i=>particles.push({kind:'bolt',x:200+Math.random()*130,y:92,tx:[658,790,886][i],ty:310,color:'#b4a1f2',born:performance.now(),life:550}));hits.forEach(i=>setTimeout(()=>burst([658,790,886][i],315,'#b4a1f2',22),250))}else{let idx=hits[0]??game.target,x=[658,790,886][idx];if(act.label==='Tidal Cut'){setLog(`${party[game.active].name} unleashes <em>Tidal Cut</em>!`);particles.push({kind:'slash',x,y:313,color:'#67ead9',start:-2.7,born:performance.now(),life:500})}else{setLog(`${party[game.active].name} strikes for <em>${game.attackBonus?'perfect ':''}impact</em>!`);particles.push({kind:'slash',x,y:313,color:game.attackBonus?'#ffe39c':'#d8e2dd',start:-2.6,born:performance.now(),life:380})}burst(x,315,game.attackBonus?'#ffe39c':'#d9ece2',12);game.shake=game.attackBonus?8:4}if(game.attackBonus){game.combo=Math.min(100,game.combo+18);setLog(`${party[game.active].name} lands a <em>perfect strike!</em> The tide surges.`)}game.action=null;renderCommands();renderParty();if(enemies.every(e=>!e.alive)){winGame();return}finishHeroTurn()}
